using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;
public static class BuildSevenPartComboPreview
{
 public static object Run()
 {
  if(Application.isPlaying)throw new Exception("Stop play first");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.name!="3DBattleDebugScene")throw new Exception("Wrong scene");const string name="New Knight Combo Sequence Preview";if(GameObject.Find(name)!=null)throw new Exception("Preview already exists");
  string[] names={"Attack 05 - Skill_03","Attack 02 - Charged_Upward_Slash","Attack 03 - Double_Combo_Attack","Attack 06 - Weapon_Combo_1","Attack 05 - Skill_03","Attack 04 - Right_Hand_Sword_Slash","Attack 01 - Attack"};int[] cuts={-1,34,41,-1,-1,-1,-1};
  var sources=names.Select(n=>GameObject.Find(n)).ToArray();if(sources.Any(s=>s==null))throw new Exception("Missing source preview");var sourceClips=sources.Select(s=>s.GetComponentInChildren<Animator>().runtimeAnimatorController.animationClips[0]).ToArray();
  var paths=sourceClips.SelectMany(c=>AnimationUtility.GetCurveBindings(c)).Select(b=>b.path).Distinct().ToArray();var root=UnityEngine.Object.Instantiate(sources[6]);root.name=name;root.transform.SetParent(null,true);var a=root.GetComponentInChildren<Animator>();a.enabled=false;
  var nodes=paths.Select(p=>a.transform.Find(p)).ToArray();if(nodes.Any(n=>n==null))throw new Exception("Missing rig path");var records=paths.ToDictionary(p=>p,p=>Enumerable.Range(0,10).Select(_=>new List<Keyframe>()).ToArray());var endIndices=new HashSet<int>();var ranges=new List<object>();var endpoints=new List<int>();int offset=0;
  try{
   for(int segment=0;segment<sources.Length;segment++){
    var temp=UnityEngine.Object.Instantiate(sources[segment]);try{var sa=temp.GetComponentInChildren<Animator>();sa.enabled=false;var clip=sourceClips[segment];int last=cuts[segment]<0?Mathf.RoundToInt(clip.length*30):cuts[segment];var sourceNodes=paths.Select(p=>sa.transform.Find(p)).ToArray();if(sourceNodes.Any(t=>t==null))throw new Exception("Rig mismatch");
     ranges.Add(new{order=segment+1,motion=clip.name,sourceFirstFrame=0,sourceLastFrame=last,comboFirstFrame=offset,comboLastFrame=offset+last});endpoints.Add(offset+last);
     for(int half=0;half<=last*2;half++){float time=(offset+half*.5f)/30;clip.SampleAnimation(sa.gameObject,Mathf.Min(half/60f,clip.length));for(int j=0;j<paths.Length;j++){var t=sourceNodes[j];var r=records[paths[j]];var p=t.localPosition;var q=t.localRotation;var scale=t.localScale;for(int c=0;c<10;c++)r[c].Add(new Keyframe(time,c<3?p[c]:c<7?q[c-3]:scale[c-7]));}if(half==last*2)endIndices.Add(records[paths[0]][0].Count-1);}
     offset+=last+1;
    }finally{UnityEngine.Object.DestroyImmediate(temp);}
   }
   var combined=new AnimationClip{name="NewKnight_ComboSequence_Preview",frameRate=30};
   foreach(var pair in records){var r=pair.Value;for(int i=1;i<r[0].Count;i++){float dot=0;for(int c=3;c<7;c++)dot+=r[c][i-1].value*r[c][i].value;if(dot<0)for(int c=3;c<7;c++){var k=r[c][i];k.value=-k.value;r[c][i]=k;}}
    for(int c=0;c<10;c++){var curve=new AnimationCurve(r[c].ToArray());for(int i=0;i<curve.length;i++){AnimationUtility.SetKeyLeftTangentMode(curve,i,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(curve,i,endIndices.Contains(i)?AnimationUtility.TangentMode.Constant:AnimationUtility.TangentMode.Linear);}var property=c<3?"m_LocalPosition."+"xyz"[c]:c<7?"m_LocalRotation."+"xyzw"[c-3]:"m_LocalScale."+"xyz"[c-7];AnimationUtility.SetEditorCurve(combined,EditorCurveBinding.FloatCurve(pair.Key,typeof(Transform),property),curve);}
   }
   var settings=AnimationUtility.GetAnimationClipSettings(combined);settings.loopTime=true;settings.loopBlend=false;AnimationUtility.SetAnimationClipSettings(combined,settings);
   const string folder="Assets/3DBattle/NewPlayer/Attack/ComboPreview";if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets/3DBattle/NewPlayer/Attack","ComboPreview");AssetDatabase.CreateAsset(combined,folder+"/"+combined.name+".anim");var controller=AnimatorController.CreateAnimatorControllerAtPath(folder+"/"+combined.name+".controller");var state=controller.layers[0].stateMachine.AddState("Combo Sequence");state.motion=combined;controller.layers[0].stateMachine.defaultState=state;a.runtimeAnimatorController=controller;a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;a.enabled=true;
   var anchor=GameObject.Find("Running Knight Preview").transform;var group=GameObject.Find("New Knight Attack Previews").transform;root.transform.SetPositionAndRotation(group.position+anchor.forward*9f+anchor.right*4f,anchor.rotation);combined.SampleAnimation(a.gameObject,0);Undo.RegisterCreatedObjectUndo(root,"Create combo sequence preview");
   float maxPosition=0,maxRotation=0;offset=0;for(int segment=0;segment<sources.Length;segment++){var temp=UnityEngine.Object.Instantiate(sources[segment]);try{var sa=temp.GetComponentInChildren<Animator>();sa.enabled=false;int last=cuts[segment]<0?Mathf.RoundToInt(sourceClips[segment].length*30):cuts[segment];for(int f=0;f<=last;f++){sourceClips[segment].SampleAnimation(sa.gameObject,f/30f);combined.SampleAnimation(a.gameObject,(offset+f)/30f);for(int j=0;j<paths.Length;j++){var src=sa.transform.Find(paths[j]);maxPosition=Mathf.Max(maxPosition,Vector3.Distance(src.localPosition,nodes[j].localPosition));maxRotation=Mathf.Max(maxRotation,Quaternion.Angle(src.localRotation,nodes[j].localRotation));}}offset+=last+1;}finally{UnityEngine.Object.DestroyImmediate(temp);}}
   combined.SampleAnimation(a.gameObject,0);var report=new{objectName=name,segments=ranges,totalFrames=offset,lastFrame=offset-1,duration=combined.length,maxPositionError=maxPosition,maxRotationError=maxRotation};var manifest=new TextAsset(Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented)){name="Combo_FrameRanges"};AssetDatabase.CreateAsset(manifest,folder+"/Combo_FrameRanges.asset");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Selection.activeGameObject=root;SceneView.lastActiveSceneView?.FrameSelected();return report;
  }catch{UnityEngine.Object.DestroyImmediate(root);throw;}
 }
}
